const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const colors=['#c89b78','#9aa489','#c99b97','#c5b16d','#8a9baa','#b4a1b8'];
let state={title:'我的旅行手帳',current:0,pages:[{title:'京都，慢慢走。',paper:'grid',items:[{id:'welcome',type:'text',text:'把日子過慢一點，\n把回憶貼近一點。',x:11,y:13,w:390,r:-3},{id:'demo',type:'photo',src:'kyoto.webp',frame:'polaroid',x:12,y:31,w:390,r:-6},{id:'tape1',type:'tape',color:0,x:30,y:29,w:200,r:5},{id:'note1',type:'text',text:'在小巷裡，遇見京都。\n一杯茶，一整個午後。',x:32,y:76,w:320,r:3},{id:'tape2',type:'tape',color:1,x:69,y:66,w:135,r:-28}]}]}, selected=null, db, saveTimer, frame='polaroid';
const page=()=>state.pages[state.current];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){clearTimeout(saveTimer);$('#saveStatus').textContent='儲存中…';saveTimer=setTimeout(()=>{if(!db){$('#saveStatus').textContent='無法儲存，請匯出留存';return}try{const tx=db.transaction('journal','readwrite');tx.objectStore('journal').put(state,'main');tx.oncomplete=()=>$('#saveStatus').textContent='已儲存在此裝置';tx.onerror=()=>{$('#saveStatus').textContent='儲存失敗';toast('儲存空間不足，請先匯出圖片')}}catch{$('#saveStatus').textContent='儲存失敗，請匯出留存'}},250)}
function tapeStyle(i){return i%2===0?`repeating-linear-gradient(45deg,transparent 0 8px,#fff5 8px 10px),${colors[i]}`:`radial-gradient(#fff8 1.5px,transparent 1.5px) 0 0/9px 9px,${colors[i]}`}
function render(){const p=page();$('#bookTitle').value=state.title;$('#pageTitle').value=p.title;$('#pageNumber').textContent=String(state.current+1).padStart(2,'0')+' / '+String(state.pages.length).padStart(2,'0');$('#pages').replaceChildren();state.pages.forEach((p,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0')+'  '+p.title;b.className=i===state.current?'active':'';b.onclick=()=>{state.current=i;selected=null;render();persist()};$('#pages').append(b)});$('#paper').className='paper '+p.paper;$$('[data-paper]').forEach(b=>b.classList.toggle('selected',b.dataset.paper===p.paper));renderItems()}
function renderItems(){$('#items').replaceChildren();const scale=$('#paper').clientWidth/640;page().items.forEach(i=>{const el=document.createElement('div');el.className='item '+(i.type==='photo'?i.frame:i.type)+(selected===i.id?' selected':'');el.dataset.id=i.id;el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-label',i.type==='photo'?'照片：按方向鍵移動':i.type==='tape'?'紙膠帶：按方向鍵移動':i.text);Object.assign(el.style,{left:i.x+'%',top:i.y+'%',width:i.w/640*100+'%',transform:`rotate(${i.r}deg)`});if(i.type==='photo'){const img=new Image();img.src=i.src;img.alt=i.id==='demo'?'京都祇園街道示範照片':'我的旅行照片';el.append(img);el.style.padding=i.frame==='polaroid'?`${10*scale}px ${10*scale}px ${32*scale}px`:'0'}if(i.type==='text'){el.textContent=i.text;el.style.fontSize=(i.id==='welcome'?30:21)*scale+'px'}if(i.type==='tape'){el.style.background=tapeStyle(i.color);el.style.height=42*scale+'px'}el.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();select(i.id);el.setPointerCapture(e.pointerId);const rect=$('#paper').getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ox=i.x,oy=i.y;el.onpointermove=ev=>{i.x=Math.max(0,Math.min(100-i.w/640*100,ox+(ev.clientX-sx)/rect.width*100));i.y=Math.max(8,Math.min(85,oy+(ev.clientY-sy)/rect.height*100));el.style.left=i.x+'%';el.style.top=i.y+'%'};el.onpointerup=()=>{el.onpointermove=null;persist()};el.onpointercancel=()=>{el.onpointermove=null;persist()}};el.onclick=()=>select(i.id);el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();select(i.id);i.x=Math.max(0,Math.min(85,i.x+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)));i.y=Math.max(8,Math.min(85,i.y+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)));el.style.left=i.x+'%';el.style.top=i.y+'%';persist()}};$('#items').append(el)});updateControls()}
function select(id){selected=id;$$('.item').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));updateControls()}
function updateControls(){const i=page().items.find(i=>i.id===selected);$('#selection').hidden=!i;if(i){$('#size').value=i.w;$('#rotation').value=i.r}}
function addItem(item){item.id=crypto.randomUUID();page().items.push({x:20,y:24,w:250,r:-4,...item});selected=item.id;renderItems();persist()}
$('#paper').onclick=e=>{if(e.target.id==='paper')select(null)};
$('#addPage').onclick=()=>{state.pages.push({title:'新的旅途片刻',paper:'grid',items:[]});state.current=state.pages.length-1;selected=null;render();persist()};
$('#bookTitle').oninput=e=>{state.title=e.target.value;persist()};$('#pageTitle').oninput=e=>{page().title=e.target.value;const nav=$('#pages .active');if(nav)nav.textContent=String(state.current+1).padStart(2,'0')+'  '+e.target.value;persist()};
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));['photo','tape','text'].forEach(t=>$('#'+t+'-panel').hidden=t!==b.dataset.tab)});
$$('[data-frame]').forEach(b=>b.onclick=()=>{frame=b.dataset.frame;$$('[data-frame]').forEach(x=>x.classList.toggle('selected',x===b));const i=page().items.find(i=>i.id===selected);if(i?.type==='photo'){i.frame=frame;renderItems();persist()}});
$$('[data-paper]').forEach(b=>b.onclick=()=>{page().paper=b.dataset.paper;render();persist()});
colors.forEach((c,i)=>{const b=document.createElement('button');b.style.background=tapeStyle(i);b.setAttribute('aria-label',['奶茶斜紋','鼠尾草圓點','玫瑰斜紋','芥黃圓點','霧藍斜紋','紫灰圓點'][i]+'紙膠帶');b.onclick=()=>addItem({type:'tape',color:i,w:210});$('#tapes').append(b)});
$('#addText').onclick=()=>{const text=$('#note').value.trim();if(!text){toast('先寫下一點文字吧');return}addItem({type:'text',text,w:320});$('#note').value=''};
$('#choosePhoto').onclick=()=>$('#photoInput').click();$('#photoInput').onchange=async e=>{const targetPage=page();for(const file of e.target.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('請選擇 JPG、PNG 或 WebP 照片');continue}try{const img=await createImageBitmap(file);const c=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(img.width,img.height));c.width=img.width*ratio;c.height=img.height*ratio;c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close();const item={id:crypto.randomUUID(),type:'photo',src:c.toDataURL('image/jpeg',.85),frame,x:18,y:22,w:290,r:-4};targetPage.items.push(item);if(page()===targetPage){selected=item.id;renderItems()}persist()}catch{toast('這張照片無法讀取，請換一張試試')}}e.target.value=''};
$('#size').oninput=e=>{const i=page().items.find(i=>i.id===selected);if(i){i.w=+e.target.value;renderItems();persist()}};$('#rotation').oninput=e=>{const i=page().items.find(i=>i.id===selected);if(i){i.r=+e.target.value;renderItems();persist()}};$('#remove').onclick=()=>{page().items=page().items.filter(i=>i.id!==selected);selected=null;renderItems();persist()};$('#front').onclick=()=>{const i=page().items.find(i=>i.id===selected);if(i){page().items=page().items.filter(x=>x!==i);page().items.push(i);renderItems();persist()}};
$('#export').onclick=async()=>{const button=$('#export');button.disabled=true;button.textContent='正在匯出…';try{await document.fonts.ready;const c=document.createElement('canvas');c.width=1280;c.height=1520;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#fffdf5';ctx.fillRect(0,0,640,760);ctx.strokeStyle='#b8b09933';ctx.lineWidth=.5;if(page().paper!=='blank'){for(let y=0;y<760;y+=page().paper==='grid'?22:28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(640,y);ctx.stroke()}if(page().paper==='grid')for(let x=0;x<640;x+=22){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,760);ctx.stroke()}}ctx.fillStyle='#9b917e';ctx.font='10px monospace';ctx.fillText('TRAVEL NOTES',38,36);for(const i of page().items){let img,h=42;if(i.type==='photo'){img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=i.src});h=i.w*img.height/img.width+(i.frame==='polaroid'?42:0)}if(i.type==='text')h=i.text.split('\n').length*(i.id==='welcome'?54:37.8);ctx.save();ctx.translate(i.x/100*640+i.w/2,i.y/100*760+h/2);ctx.rotate(i.r*Math.PI/180);ctx.translate(-i.w/2,-h/2);if(img){const pad=i.frame==='polaroid'?10:0;if(pad){ctx.fillStyle='#fff';ctx.fillRect(0,0,i.w,h)}ctx.drawImage(img,pad,pad,i.w-pad*2,h-(pad?42:0))}else if(i.type==='tape'){ctx.globalAlpha=.82;ctx.fillStyle=colors[i.color];ctx.fillRect(0,0,i.w,42);ctx.fillStyle='#ffffff66';if(i.color%2)for(let x=3;x<i.w;x+=9)for(let y=3;y<42;y+=9){ctx.beginPath();ctx.arc(x,y,1.5,0,7);ctx.fill()}else{ctx.strokeStyle='#ffffff66';for(let x=-42;x<i.w;x+=14){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x+42,42);ctx.stroke()}}}else{const font=i.id==='welcome'?30:21;ctx.font=`${font}px "Noto Serif TC",serif`;ctx.fillStyle='#4c4439';ctx.textBaseline='top';let line='',y=0;for(const ch of i.text){if(ch==='\n'||ctx.measureText(line+ch).width>i.w){ctx.fillText(line,0,y);y+=font*1.8;line=ch==='\n'?'':ch}else line+=ch}ctx.fillText(line,0,y)}ctx.restore()}ctx.fillStyle='#9b917e';ctx.font='italic 12px Georgia';ctx.textAlign='center';ctx.fillText('a little moment, a lovely memory.',320,738);if(page().items.some(i=>i.id==='demo')){ctx.font='8px sans-serif';ctx.fillText('Photo: isoyan / Wikimedia Commons / CC BY-SA 3.0',320,751)}const a=document.createElement('a');a.download=(page().title||'旅行手帳')+'.png';a.href=c.toDataURL('image/png');a.click();toast('已匯出這一頁')}catch{toast('匯出失敗，請稍後再試')}finally{button.disabled=false;button.textContent='匯出這一頁 ↗'}};
const credit=document.createElement('p');credit.className='local-note';credit.innerHTML='示範照片：<a href="https://commons.wikimedia.org/wiki/File:Gion_kyoto_japan.JPG" target="_blank" rel="noopener">isoyan / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener">CC BY-SA 3.0</a>';$('.materials').append(credit);
render();const request=indexedDB.open('tabi-paper-journal',1);request.onupgradeneeded=()=>request.result.createObjectStore('journal');request.onsuccess=()=>{db=request.result;const r=db.transaction('journal').objectStore('journal').get('main');r.onsuccess=()=>{if(r.result?.pages?.length){state=r.result;render()}$('#saveStatus').textContent='已儲存在此裝置'};r.onerror=()=>$('#saveStatus').textContent='讀取失敗，請重新開啟'};request.onerror=()=>$('#saveStatus').textContent='無法儲存，請匯出留存';new ResizeObserver(()=>renderItems()).observe($('#paper'));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_journal_note',description:'在目前的旅行手帳頁面新增文字。',inputSchema:{type:'object',properties:{text:{type:'string',minLength:1,maxLength:1000}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.text!=='string'||!input.text.trim()||input.text.length>1000)throw new Error('請提供 1 至 1000 字的文字');addItem({type:'text',text:input.text,w:320});return {added:true,page:page().title}}})).catch(()=>{})}catch{}}
